 w=new(){EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(2,18);w.SetWorld(0);w.SetCast(123);w.SetPlacement(456);w.Relations.Reset();w.SelectPlayer(0);w.HumanPlayers.AddRange(new[]{0,1});w.Robots.Initialize(w.Nodes.All.Length,w.ActiveCount);w.Robots.ConfigureFactories(w);
