 Set("_setup",w);Set("_world",new WorldPreview(GraphicsDevice));Set("_autoSaveEnabled",false);Set("_statisticsEnabled",false);Set("_conquestOverviewTurn",w.Population.Turn);Set("_diplomacyPending",true);Set("_screen",Enum.Parse(Get("_screen").GetType(),"WorldStatus"));Set("_conquestOverview",true);Check(!(bool)Call("TryBeginTurnNewspaper"),"overview precedes newspaper");Set("_conquestOverview",false);Check((bool)Call("TryBeginTurnNewspaper"),"newspaper begins before diplomacy");Check(w.Campaign.Trade.Offers.Contains(offer),"reading cannot answer offer");Check(!(bool)Call("TryBeginTurnNewspaper"),"active newspaper cannot restart");
